/**
 * Durable process output for managed architecture-v2 agents.
 *
 * The host persists a bounded snapshot of stdout and stderr after masking
 * credential tokens. Writes happen at flush boundaries rather than per line.
 */
import { readFile } from "node:fs/promises";
import { cursorHostedFiles } from "../files-backends/cursor-hosted.js";
import { agentSdkStorageKeys } from "../storage-protocol.js";
import { resolveApiKeySync } from "./cursor/credentials.js";
import { describeError, describeErrorCode } from "./describe-error.js";
import { resolveAgentV2Hosting } from "./v2-hosting.js";
/** Maximum bytes retained in each persisted output snapshot. */
export const START_LOG_STORE_MAX_BYTES = 2 * 1024 * 1024;
/** Default local output path. */
export const DEFAULT_ENGINE_START_LOG_PATH = "/workspace/.agent-serve/start.log";
function decodeSinkBody(body) {
    return body instanceof Uint8Array ? body : body.body;
}
export function tailStartLogText(raw, maxBytes) {
    const encoded = new TextEncoder().encode(raw);
    if (encoded.byteLength <= maxBytes) {
        return raw;
    }
    return new TextDecoder().decode(encoded.subarray(encoded.byteLength - maxBytes));
}
/** Each character literally or percent-encoded, as tokens appear in URLs. */
function encodable(text) {
    return Array.from(text, (char) => {
        const lower = char.charCodeAt(0).toString(16).padStart(2, "0");
        const upper = char.toUpperCase().charCodeAt(0).toString(16).padStart(2, "0");
        return lower === upper ? `(?:${char}|%${lower})` : `(?:${char}|%${lower}|%${upper})`;
    }).join("");
}
const HEX = String.raw `(?:[a-f0-9]|%(?:3[0-9]|[46][1-6]))`;
const TOKEN_MASKS = [
    [new RegExp(`${encodable("grok_")}${HEX}{32}${encodable("_")}${HEX}{64}`, "gi"), "grok_…"],
    [new RegExp(`${encodable("crsr_")}(?:[a-z0-9_-]|%[0-9a-f]{2})+`, "gi"), "crsr_…"],
    [/\bghs_[A-Za-z0-9_]+\b/g, "ghs_…"],
    [/\bgho_[A-Za-z0-9_]+\b/g, "gho_…"],
    [/\bxox[baprs]-[A-Za-z0-9-]+\b/g, "xox…"],
];
/** Mask credential tokens before persisting a snapshot. */
export function maskStartLogTokens(text) {
    return TOKEN_MASKS.reduce((masked, [pattern, mask]) => masked.replace(pattern, mask), text);
}
export function resolveEngineStartLogPath(env = process.env) {
    const configured = env.AGENT_SERVE_ENGINE_START_LOG_PATH?.trim();
    return configured !== undefined && configured.length > 0
        ? configured
        : DEFAULT_ENGINE_START_LOG_PATH;
}
/**
 * Read the local engine tee. Missing/empty is `undefined` (no store write).
 * Soft-fail: a local read error must not change hosted-execution HTTP.
 */
export async function readLocalStartLogText(args) {
    const path = args?.path ?? resolveEngineStartLogPath();
    const maxBytes = args?.maxBytes ?? START_LOG_STORE_MAX_BYTES;
    try {
        const raw = await readFile(path, "utf8");
        if (raw.length === 0) {
            return undefined;
        }
        return tailStartLogText(raw, maxBytes);
    }
    catch (error) {
        if (describeErrorCode(error) === "ENOENT") {
            return undefined;
        }
        return undefined;
    }
}
export function createStartLogStore(input) {
    const { sink, agentName } = input;
    const logger = input.logger ?? (() => { });
    // Flush moments often find the tee unchanged (a quiet turn, the claim then
    // the stamp); skip a put that would store the same bytes again.
    let stored;
    return {
        async persist(startLogId, contents) {
            const key = agentSdkStorageKeys.log(agentName, startLogId);
            const body = maskStartLogTokens(tailStartLogText(contents, START_LOG_STORE_MAX_BYTES));
            if (stored?.key === key && stored.body === body) {
                return;
            }
            try {
                await sink.put(key, new TextEncoder().encode(body));
                stored = { key, body };
            }
            catch (error) {
                logger(`[bdk] start-log: persist failed for ${startLogId} (${describeError(error)})`);
            }
        },
        async read(startLogId) {
            const key = agentSdkStorageKeys.log(agentName, startLogId);
            try {
                const body = await sink.get(key);
                if (body === undefined) {
                    return undefined;
                }
                const text = new TextDecoder().decode(decodeSinkBody(body));
                return text.length === 0 ? undefined : text;
            }
            catch (error) {
                logger(`[bdk] start-log: read failed for ${startLogId} (${describeError(error)})`);
                return undefined;
            }
        },
    };
}
/**
 * Freeze pods only. A persistent slot writes one file per command under
 * `/state/logs` and mirrors that directory; this store is the single
 * `start.log` tee those pods do not produce.
 */
export function selectStartLogStore(input) {
    const hosting = resolveAgentV2Hosting({
        architecture: input.project.agent.architecture,
        env: input.env,
    });
    if (hosting.kind !== "cursor-managed") {
        return undefined;
    }
    return createStartLogStore({
        sink: cursorHostedFiles({
            resolveStoreSourceId: () => hosting.resolveStoreIds().frameworkStoreSourceId,
            resolveApiKey: () => resolveApiKeySync()?.apiKey,
        }),
        agentName: input.project.name,
        logger: input.logger,
    });
}
/**
 * Snapshot the local tee into the store. No-op when the file is missing
 * or empty. Soft-fail inside {@link StartLogStore.persist}.
 */
const flushing = new WeakMap();
/**
 * Flushes on one store run one at a time, each reading the tee when its turn
 * comes, so a slow earlier put cannot land over a later, longer snapshot.
 */
export function flushLocalStartLog(args) {
    const run = (flushing.get(args.store) ?? Promise.resolve()).then(async () => {
        const contents = await readLocalStartLogText(args.path === undefined ? undefined : { path: args.path });
        if (contents !== undefined) {
            await args.store.persist(args.startLogId, contents);
        }
    });
    flushing.set(args.store, run.catch(() => undefined));
    return run;
}
